#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(Seurat);library(data.table);library(Matrix)})
args<-commandArgs(trailingOnly=TRUE)
if(length(args)!=6L)stop('Usage: 03_run_phase77_singlecell_transfer_v1.R <dataset> <rds> <metadata> <signature> <cycle> <out>')
dataset<-args[[1]];rds<-normalizePath(args[[2]],winslash='/',mustWork=TRUE);metadata_path<-normalizePath(args[[3]],winslash='/',mustWork=TRUE)
signature_path<-normalizePath(args[[4]],winslash='/',mustWork=TRUE);cycle_path<-normalizePath(args[[5]],winslash='/',mustWork=TRUE);out<-normalizePath(args[[6]],winslash='/',mustWork=FALSE);part<-paste0(out,'.part')
if(!(dataset%chin%c('GSE207493','GSE264586','GSE294109')))stop('unexpected dataset')
if(dir.exists(out)||file.exists(out)||dir.exists(part)||file.exists(part))stop('refusing existing output');dir.create(part,recursive=TRUE)
MIN_CELLS<-50L
OUTCOMES<-list(SPP1_STATE_NO_SPP1=c('GPNMB','LGALS3','FABP5','CD9','LPL'),IMMUNOSUPPRESSION_NO_IL10=c('TGFB1','VSIG4','MARCO','CD274','IDO1'))
REL<-data.table(relation_id=c('Q01_DIRECT_MTA_to_SPP1_STATE','Q02_DIRECT_MTA_to_IMMUNOSUPPRESSION'),outcome=names(OUTCOMES),expected_direction=1L)
atomic_fwrite<-function(x,p){tmp<-paste0(p,'.part');fwrite(x,tmp,sep='\t',quote=TRUE,na='NA');if(!file.rename(tmp,p))stop('rename failed')}
score_matched_control<-function(expression,genes,ctrl_size,n_bins=25L,seed=2621077L){genes<-unique(intersect(toupper(genes),rownames(expression)));if(length(genes)<10L)return(NULL);avg<-Matrix::rowMeans(expression);finite<-is.finite(avg);pool<-rownames(expression)[finite];pa<-avg[finite];n_items<-as.integer(round(length(pa)/(n_bins-1L)));rank<-frank(pa,ties.method='min');bins<-floor(rank/n_items);names(bins)<-pool;set.seed(seed);controls<-character();for(bin in unique(bins[genes])){cand<-names(bins)[bins==bin&!names(bins)%chin%genes];if(length(cand)>ctrl_size)cand<-sample(cand,ctrl_size,FALSE);controls<-union(controls,cand)};if(!length(controls))stop('no controls');list(score=as.numeric(Matrix::colMeans(expression[genes,,drop=FALSE])-Matrix::colMeans(expression[controls,,drop=FALSE]))) }
weighted_score<-function(expression,sig,exclude){s<-sig[!human_symbol%chin%exclude];present<-s[human_symbol%chin%rownames(expression)];up<-sum(present$direction=='UP');down<-sum(present$direction=='DOWN');coverage<-nrow(present)/nrow(s);eligible<-coverage>=0.70&&up>=8L&&down>=8L;if(!eligible)return(list(score=rep(NA_real_,ncol(expression)),coverage=coverage,up=up,down=down,present=paste(present$human_symbol,collapse=';'),eligible=FALSE));m<-as.matrix(expression[present$human_symbol,,drop=FALSE]);sdv<-apply(m,1,sd);z<-matrix(0,nrow=nrow(m),ncol=ncol(m),dimnames=dimnames(m));v<-is.finite(sdv)&sdv>0;z[v,]<-sweep(sweep(m[v,,drop=FALSE],1,rowMeans(m[v,,drop=FALSE]),'-'),1,sdv[v],'/');signed<-ifelse(present$direction=='UP',1,-1);w<-present$weight;list(score=as.numeric(colSums(z*(w*signed))/sum(w)),coverage=coverage,up=up,down=down,present=paste(present$human_symbol,collapse=';'),eligible=TRUE)}
program_score<-function(expression,genes){g<-intersect(genes,rownames(expression));if(length(g)<3L)stop('outcome coverage');m<-as.matrix(expression[g,,drop=FALSE]);sdv<-apply(m,1,sd);z<-matrix(0,nrow=nrow(m),ncol=ncol(m));v<-is.finite(sdv)&sdv>0;z[v,]<-sweep(sweep(m[v,,drop=FALSE],1,rowMeans(m[v,,drop=FALSE]),'-'),1,sdv[v],'/');colMeans(z)}
residualize<-function(v,s,g)as.numeric(lm.fit(cbind(Intercept=1,S=s,G2M=g),v)$residuals)
safe_rho<-function(x,y)if(uniqueN(x)<3L||uniqueN(y)<3L)NA_real_ else suppressWarnings(cor(x,y,method='spearman'))
signed_rank<-function(v){v<-v[is.finite(v)];if(!length(v)||all(abs(v)<1e-15))return(c(stat=0,p=1));x<-suppressWarnings(wilcox.test(v,mu=0,alternative='two.sided',exact=length(v)<50L));c(stat=unname(x$statistic),p=x$p.value)}
meta<-fread(metadata_path)
if(dataset=='GSE207493'){meta<-meta[cell_type%chin%c('Myeloid','Dendritic')];meta[,`:=`(cell_id=cell_barcode,seurat_cell_name=paste0('GSE207493__GSE207493__',sub('^([^_]+)_','\\1__',cell_barcode)),patient_key=paste0('GSE207493::',sample),patient_id=sample,timepoint='Single')]}else{meta<-meta[phase7_broad_annotation=='Myeloid']}
obj<-readRDS(rds);eall<-LayerData(obj[['RNA']],layer='data');missing<-setdiff(meta$seurat_cell_name,colnames(eall));if(length(missing))stop('metadata mismatch ',length(missing));expression<-eall[,meta$seurat_cell_name,drop=FALSE];colnames(expression)<-meta$cell_id;rm(obj,eall);invisible(gc())
upper<-toupper(rownames(expression));collision<-unique(upper[duplicated(upper)|duplicated(upper,fromLast=TRUE)]);keep<-!upper%chin%collision;expression<-expression[keep,,drop=FALSE];rownames(expression)<-upper[keep]
sig<-fread(signature_path)[signature_id=='DIRECT_MTA_GSE249082'];if(nrow(sig)!=89L)stop('unexpected direct signature size')
cycle<-fread(cycle_path);sg<-toupper(cycle[phase=='S',gene]);gg<-toupper(cycle[phase=='G2M',gene]);ss<-score_matched_control(expression,sg,min(length(sg),length(gg)));gs<-score_matched_control(expression,gg,min(length(sg),length(gg)));if(is.null(ss)||is.null(gs))stop('cycle score failed')
scores<-data.table(cell_id=colnames(expression),S_score=ss$score,G2M_score=gs$score)
coverage<-list();ci<-0L
for(name in names(OUTCOMES)){ws<-weighted_score(expression,sig,OUTCOMES[[name]]);scores[[paste0('DIRECT_MTA_FOR_',name)]]<-ws$score;scores[[name]]<-program_score(expression,OUTCOMES[[name]]);ci<-ci+1L;coverage[[ci]]<-data.table(dataset=dataset,outcome=name,frozen_genes=nrow(sig)-sum(sig$human_symbol%chin%OUTCOMES[[name]]),present_fraction=ws$coverage,present_up=ws$up,present_down=ws$down,eligible=ws$eligible,present_genes=ws$present)}
scores<-cbind(meta[,.(cell_id,patient_key,patient_id,timepoint)],scores[,!"cell_id",with=FALSE])
rows<-list();ri<-0L
groups<-unique(scores[,.(patient_key,timepoint)])
for(j in seq_len(nrow(groups))){k<-groups[j];d<-scores[patient_key==k$patient_key&timepoint==k$timepoint];if(nrow(d)<MIN_CELLS)next;for(i in seq_len(nrow(REL))){rel<-REL[i];x<-d[[paste0('DIRECT_MTA_FOR_',rel$outcome)]];y<-d[[rel$outcome]];ok<-is.finite(x)&is.finite(y)&is.finite(d$S_score)&is.finite(d$G2M_score);if(sum(ok)<MIN_CELLS)next;xr<-residualize(x[ok],d$S_score[ok],d$G2M_score[ok]);yr<-residualize(y[ok],d$S_score[ok],d$G2M_score[ok]);ri<-ri+1L;rows[[ri]]<-data.table(dataset=dataset,relation_id=rel$relation_id,patient_key=k$patient_key,patient_id=d$patient_id[1],timepoint=k$timepoint,n_cells=sum(ok),rho=safe_rho(xr,yr))}}
unit<-rbindlist(rows);patient<-unit[,.(patient_median_rho=median(rho,na.rm=TRUE),n_timepoints=uniqueN(timepoint),total_cells=sum(n_cells)),by=.(dataset,relation_id,patient_key)]
summary<-patient[,{test<-signed_rank(patient_median_rho);pos<-sum(patient_median_rho>0);neg<-sum(patient_median_rho<0);list(n_patients=.N,total_cells=sum(total_cells),median_rho=median(patient_median_rho),positive_patients=pos,negative_patients=neg,positive_fraction=pos/(pos+neg),p_value=test[['p']])},by=.(dataset,relation_id)]
summary[,q_value:=p.adjust(p_value,'BH')];summary[,statistical_status:=fifelse(q_value<0.05&median_rho>0&positive_fraction>=2/3,'COHORT_SUPPORTED','NOT_SUPPORTED')];summary[,evidence_use:='EXPLORATORY_DIRECT_SIGNATURE_ONLY']
status<-data.table(dataset=dataset,selected_cells=nrow(meta),eligible_patients=uniqueN(patient$patient_key),relations=nrow(summary),status='PASS_PHASE77_SINGLECELL_TRANSFER')
atomic_fwrite(rbindlist(coverage),file.path(part,paste0(dataset,'_signature_coverage_v1.tsv')));atomic_fwrite(unit,file.path(part,paste0(dataset,'_unit_correlations_v1.tsv.gz')));atomic_fwrite(patient,file.path(part,paste0(dataset,'_patient_correlations_v1.tsv')));atomic_fwrite(summary,file.path(part,paste0(dataset,'_relation_summary_v1.tsv')));atomic_fwrite(status,file.path(part,paste0(dataset,'_status_v1.tsv')))
if(!file.rename(part,out))stop('rename failed');cat(sprintf('{"status":"PASS_PHASE77_SINGLECELL_TRANSFER","dataset":"%s","patients":%d}\n',dataset,uniqueN(patient$patient_key)))
